face.layout_source:
// two-buses.face: the panel for tap/examples/graphs/two-buses.tap.
//
// Only layout lives here.  The style is a theme from face/themes, chosen per
// family in face/themes/families.json:
//
//   facec face/themes/<theme>.face tap/examples/graphs/two-buses.face --meta <graph>.cragmeta

face "Two Buses" {
  row(gap = 10) {
    box "Voice Sidechain" { knob.big "Depth" (depth) knob "Threshold" (music_duck.threshold) knob "Ratio" (music_duck.ratio) }
    box "Music" {
      knob "L Attack" (ml.attack) knob "L Release" (ml.release) knob "R Attack" (mr.attack) knob "R Release" (mr.release)
    }
    box "FX" { knob "L Attack" (fl.attack) knob "L Release" (fl.release) knob "R Attack" (fr.attack) knob "R Release" (fr.release) }
  }
}
